-- Additive, durable S3 deletion outbox for explicitly removed READY
-- attachments. The object key is generated by the backend, never the user.
-- No existing rows or S3 objects are modified by Flyway.
CREATE TABLE attachment_object_delete_queue (
    object_key VARCHAR(256) PRIMARY KEY,
    owner_id UUID NOT NULL REFERENCES app_user(id),
    queued_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    retry_after TIMESTAMPTZ NOT NULL DEFAULT now(),
    attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0)
);
CREATE INDEX idx_attachment_object_delete_retry
    ON attachment_object_delete_queue(retry_after, queued_at);
